    },
    {
      "fact_text": {
        "text": "The continue statement moves control to the beginning of a loop.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A loop condition can be simplified to `true` so the loop runs forever until a break statement ends it.",
        "refs": ["Q0004", "Q0005"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Handle user input with break and continue statements",
        "refs": ["Q0001", "Q0002", "Q0003"]
      },
      "prerequisites": null,
      "steps": [
        {
          "text": "Read user input.",
          "refs": ["Q0000"]
        },
        {
          "text": "If the input equals \"quit\", execute a `break` statement to terminate the loop.",
          "refs": ["Q0001", "Q0002"]
        },
        {
          "text": "Else if the input equals \"pass\", execute a `continue` statement to skip the rest of the loop body and start the next iteration.",
          "refs": ["Q0003"]
        },
        {
          "text": "Otherwise, print the input.",
          "refs": ["Q0000"]
        }
      ],
      "outcomes": null,
      "content": {
        "text": "This procedure ensures that the word \"quit\" ends the program without being echoed, \"pass\" causes the loop to restart without echoing, and all other inputs are echoed back.",
        "refs": ["Q0000", "Q0001", "Q0002", "Q0003"]
      }
    }
  ],
  "relationships": [],
  "explanations": [
    {
      "topic": {
        "text": "Break and continue statements in loops",
        "refs": ["Q0002", "Q0003"]
      },
      "explanation_text": {
        "text": "When Java encounters a `break` statement inside a loop, it exits the loop immediately, ignoring any remaining statements in the current iteration. When it encounters a `continue` statement, it skips the remaining statements of the current iteration and jumps to the next iteration by moving control to the beginning of the loop.",
        "refs": ["Q0002", "Q0003"]
      },
      "explanation_type": null
    }
  ],
